#[using="Type"] Lemma art_clspop_A : forall regs (M rom : word -> option byte) (raw : word) (sp st c r req spb qs au mu km need : Z),
  getr regs 1 = raw -> getr regs 2 = Z_to_bv 64 sp -> getr regs 10 = Z_to_bv 64 1303448 -> getr regs 11 = Z_to_bv 64 st -> getr regs 12 = Z_to_bv 64 c ->
  getr regs 13 = Z_to_bv 64 r -> getr regs 14 = Z_to_bv 64 req ->
  0x698000 + 464 <= sp -> sp < 2 ^ 47 -> 0 <= st < 2 ^ 64 -> 1 <= c <= 30 -> 0x698000 <= r -> r + 128 < 2 ^ 47 ->
  1 <= req <= 8 -> need = AsanTab.class_size c * req -> 0 <= spb -> spb + 2 ^ 37 < 2 ^ 47 -> spb = 65536 * qs -> mu = 262144 * km ->
  0 <= au -> au <= mu -> mu < au + need -> need <= 2 ^ 18 -> mu + 2 ^ 18 <= 3758096384 ->
  apart (sp - 464) 464 r 128 ->
  wrA M (sp - 464) 464 ->
  cellA M (1303448 + 32) 8 spb -> cellA M (r + 32) 8 au -> cellA M (r + 48) 8 mu -> cellA M (r + 56) 8 0 -> cellA M (1303448 + 56) 1 0 -> cellA M (1303448 + 40) 4 0xffffffff ->
  cellA M 0x139198 8 0x1d14a0 -> cellA M 0x1d14a0 8 4096 -> cellA M 0x1391a8 8 0x1d3528 -> cellA M (0x1d3528 + 260) 1 0 ->
  exists regs' M',
    msteps ASEGS (mkst regs (0x5807c : word) M rom) (mkst regs' (0x8c604 : word) M' rom)
    /\ art_mmap_args regs' (spb + c * 2 ^ 32 + mu) 262144 50
    /\ getr regs' 1 = Z_to_bv 64 0x8e3c4 /\ getr regs' 2 = Z_to_bv 64 (sp - 64 - 128) /\ getr regs' 8 = Z_to_bv 64 262144
    /\ getr regs' 21 = Z_to_bv 64 (AsanTab.class_size c) /\ getr regs' 22 = Z_to_bv 64 1303448
    /\ (forall x : reg, In x [3; 4; 23; 24; 25; 26; 27]%bv -> getr regs' x = getr regs x)
    /\ mem_grows M M' /\ art_agree [(sp - 464, 464)] M M'
    /\ cellA M' (sp - 8) 8 (U raw) /\ cellA M' (sp - 16) 8 (U (getr regs 8)) /\ cellA M' (sp - 24) 8 (U (getr regs 9)) /\ cellA M' (sp - 32) 8 (U (getr regs 18))
    /\ cellA M' (sp - 40) 8 (U (getr regs 19)) /\ cellA M' (sp - 48) 8 (U (getr regs 20)) /\ cellA M' (sp - 56) 8 (U (getr regs 21)) /\ cellA M' (sp - 64) 8 (U (getr regs 22))
    /\ cellA M' (sp - 64 - 8) 8 0x5819c /\ cellA M' (sp - 64 - 16) 8 r /\ cellA M' (sp - 64 - 24) 8 st /\ cellA M' (sp - 64 - 32) 8 (spb + c * 2 ^ 32)
    /\ cellA M' (sp - 64 - 40) 8 0x9657c /\ cellA M' (sp - 64 - 48) 8 262144 /\ cellA M' (sp - 64 - 56) 8 (spb + c * 2 ^ 32 + mu)
    /\ cellA M' (sp - 64 - 64) 8 (spb + c * 2 ^ 32) /\ cellA M' (sp - 64 - 72) 8 262144 /\ cellA M' (sp - 64 - 80) 8 (spb + c * 2 ^ 32 + mu).
